begin;

select extensions.no_plan();

-- Synthetic-only P19-01 graph. Direct inserts as the owner bypass RLS; the
-- schema is deny-by-default with zero base grants and no browser policies.
insert into public.organizations (id, legal_name, business_name, slug) values
  ('f0100000-0000-0000-0000-000000000001','P1901 Synthetic A Inc.','P1901 A','p1901-a'),
  ('f0100000-0000-0000-0000-000000000002','P1901 Synthetic B Inc.','P1901 B','p1901-b');
insert into auth.users (id, instance_id, aud, role, email, encrypted_password, email_confirmed_at, raw_app_meta_data, raw_user_meta_data, created_at, updated_at) values
  ('e1010000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','p1901-user@example.test','',statement_timestamp(),'{}','{}',statement_timestamp(),statement_timestamp());
insert into public.branches (id, organization_id, name, slug, code, address_line1, city, province) values
  ('f0200000-0000-0000-0000-000000000001','f0100000-0000-0000-0000-000000000001','P1901 A Main','p1901-a-main','P1901-A','1 Synthetic St','Test City','Test Province'),
  ('f0200000-0000-0000-0000-000000000002','f0100000-0000-0000-0000-000000000001','P1901 A Branch 2','p1901-a-2','P1901-A2','2 Synthetic St','Test City','Test Province'),
  ('f0200000-0000-0000-0000-000000000003','f0100000-0000-0000-0000-000000000002','P1901 B Main','p1901-b-main','P1901-B','3 Synthetic St','Test City','Test Province'),
  ('f0200000-0000-0000-0000-000000000004','f0100000-0000-0000-0000-000000000002','P1901 B Branch 2','p1901-b-2','P1901-B2','4 Synthetic St','Test City','Test Province');
insert into public.inventory_items (id, organization_id, code, name, category, unit, reorder_level, lot_tracking) values
  ('f0300000-0000-0000-0000-000000000001','f0100000-0000-0000-0000-000000000001','ANESTHETIC','Anesthetic 2% Cartridge','CONSUMABLE','box',10,true),
  ('f0300000-0000-0000-0000-000000000002','f0100000-0000-0000-0000-000000000001','GLOVES','Surgical Gloves','CONSUMABLE','pair',10,false),
  ('f0300000-0000-0000-0000-000000000003','f0100000-0000-0000-0000-000000000002','FOREIGN_ITEM','Foreign Item','CONSUMABLE','unit',0,false);
insert into public.inventory_stock (id, organization_id, branch_id, item_id, quantity_on_hand) values
  ('f0400000-0000-0000-0000-000000000001','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001',5);
insert into public.inventory_transfers (id, organization_id, source_branch_id, destination_branch_id, item_id, quantity, status) values
  ('f0500000-0000-0000-0000-000000000001','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',3,'SENT'),
  ('f0500000-0000-0000-0000-000000000002','f0100000-0000-0000-0000-000000000002','f0200000-0000-0000-0000-000000000003','f0200000-0000-0000-0000-000000000004','f0300000-0000-0000-0000-000000000003',1,'SENT');
insert into public.inventory_movements (id, organization_id, branch_id, item_id, movement_type, quantity_delta, transfer_id) values
  ('f0600000-0000-0000-0000-000000000001','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001','RECEIPT',5,null);

select extensions.columns_are('public','inventory_items',array['id','organization_id','code','name','category','unit','reorder_level','lot_tracking','is_active','version','created_at','updated_at'],'inventory_items has only the approved P19-01 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.inventory_items'::regclass),'inventory_items has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.inventory_items',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no inventory_items privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='inventory_items'),0,'inventory_items is deny-by-default with no browser policies');
select extensions.is((select count(*)::integer from pg_indexes where schemaname='public' and tablename='inventory_items' and indexname='inventory_items_organization_active_code_idx'),1,'inventory_items indexes the org+active+code catalog access path');

select extensions.columns_are('public','inventory_stock',array['id','organization_id','branch_id','item_id','quantity_on_hand','reorder_level_override','version','updated_at'],'inventory_stock has only the approved P19-01 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.inventory_stock'::regclass),'inventory_stock has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.inventory_stock',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no inventory_stock privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='inventory_stock'),0,'inventory_stock is deny-by-default with no browser policies');

select extensions.columns_are('public','inventory_transfers',array['id','organization_id','source_branch_id','destination_branch_id','item_id','quantity','status','reason','created_by','confirmed_by','confirmed_at','version','created_at','updated_at'],'inventory_transfers has only the approved P19-01 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.inventory_transfers'::regclass),'inventory_transfers has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.inventory_transfers',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no inventory_transfers privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='inventory_transfers'),0,'inventory_transfers is deny-by-default with no browser policies');
select extensions.is((select count(*)::integer from pg_indexes where schemaname='public' and tablename='inventory_transfers' and indexname='inventory_transfers_organization_source_status_idx'),1,'inventory_transfers indexes the org+source+status access path');
select extensions.is((select count(*)::integer from pg_indexes where schemaname='public' and tablename='inventory_transfers' and indexname='inventory_transfers_organization_destination_status_idx'),1,'inventory_transfers indexes the org+destination+status access path');

select extensions.columns_are('public','inventory_movements',array['id','organization_id','branch_id','item_id','movement_type','quantity_delta','reason','transfer_id','lot_number','expiry_date','recorded_by','recorded_at'],'inventory_movements has only the approved P19-01 fields');
select extensions.ok((select relrowsecurity from pg_class where oid = 'public.inventory_movements'::regclass),'inventory_movements has RLS enabled');
select extensions.ok(not exists(select 1 from (values(0::oid),((select oid from pg_roles where rolname='anon')),((select oid from pg_roles where rolname='authenticated')),((select oid from pg_roles where rolname='service_role'))) as role(role_oid) cross join (values('SELECT'),('INSERT'),('UPDATE'),('DELETE'),('TRUNCATE'),('REFERENCES'),('TRIGGER')) as privilege(name) where has_table_privilege(role.role_oid,'public.inventory_movements',privilege.name)),'PUBLIC, anon, authenticated, and service_role have no inventory_movements privileges');
select extensions.is((select count(*)::integer from pg_policies where schemaname='public' and tablename='inventory_movements'),0,'inventory_movements is deny-by-default with no browser policies');
select extensions.is((select count(*)::integer from pg_indexes where schemaname='public' and tablename='inventory_movements' and indexname='inventory_movements_organization_branch_recorded_idx'),1,'inventory_movements indexes the org+branch+recorded_at ledger access path');
select extensions.is((select count(*)::integer from pg_indexes where schemaname='public' and tablename='inventory_movements' and indexname='inventory_movements_organization_item_idx'),1,'inventory_movements indexes the org+item ledger access path');

select extensions.is((select count(*)::integer from pg_proc where oid = 'private.protect_inventory_movements()'::regprocedure and proconfig = array['search_path=""']::text[]),1,'protect_inventory_movements pins an empty search path');
select extensions.ok(not exists (
  select 1 from pg_proc as proc
  where proc.oid = 'private.protect_inventory_movements()'::regprocedure
    and (
      has_function_privilege('public', proc.oid, 'execute')
      or has_function_privilege('anon', proc.oid, 'execute')
      or has_function_privilege('authenticated', proc.oid, 'execute')
      or has_function_privilege('service_role', proc.oid, 'execute')
    )
),'the inventory movements append-only trigger function is revoked from every role');
select extensions.is((select count(*)::integer from pg_trigger where tgname='inventory_movements_protect_append_only' and not tgisinternal),1,'inventory_movements_protect_append_only is wired to the movement ledger');

-- inventory_items constraints.
select extensions.lives_ok($$insert into public.inventory_items (id,organization_id,code,name,category,unit,reorder_level,lot_tracking) values ('f0300000-0000-0000-0000-000000000004','f0100000-0000-0000-0000-000000000001','SUTURES','Suture','CONSUMABLE','box',0,false)$$,'an inventory item is accepted at version one with defaults');
select extensions.is((select is_active and version=1 and lot_tracking=false from public.inventory_items where id='f0300000-0000-0000-0000-000000000004'),true,'inventory_items defaults to active, lot-tracking off, at version one');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','lower','Lowercase Code','CONSUMABLE','box')$$,'23514',null,'inventory item codes must be uppercase');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','WITH SPACE','With Space','CONSUMABLE','box')$$,'23514',null,'inventory item codes must match the uppercase underscore pattern');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001',repeat('C',81),'Too Long Code','CONSUMABLE','box')$$,'23514',null,'inventory item codes are bounded to 80 characters');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','BLANK','   ','CONSUMABLE','box')$$,'23514',null,'blank inventory item names are rejected');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','LONG',repeat('n',161),'CONSUMABLE','box')$$,'23514',null,'inventory item names are bounded to 160 characters');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','BADCAT','Bad Category','TOOL','box')$$,'23514',null,'inventory item category is bounded to CONSUMABLE/EQUIPMENT');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','BADUNIT','Bad Unit','CONSUMABLE','   ')$$,'23514',null,'blank inventory item units are rejected');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit,reorder_level) values ('f0100000-0000-0000-0000-000000000001','NEGREORDER','Negative Reorder','CONSUMABLE','box',-1)$$,'23514',null,'inventory item reorder_level cannot be negative');
select extensions.throws_ok($$insert into public.inventory_items (id,organization_id,code,name,category,unit,version) values ('f0300000-0000-0000-0000-000000000005','f0100000-0000-0000-0000-000000000001','ZEROVERSION','Zero Version','CONSUMABLE','box',0)$$,'23514',null,'inventory item version must be positive');
select extensions.throws_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000001','ANESTHETIC','Duplicate','CONSUMABLE','box')$$,'23505',null,'the (organization_id, code) key rejects duplicate item codes in the same organization');
select extensions.lives_ok($$insert into public.inventory_items (organization_id,code,name,category,unit) values ('f0100000-0000-0000-0000-000000000002','ANESTHETIC','Same Code Other Org','CONSUMABLE','box')$$,'an inventory item code is scoped to its organization, so another organization may reuse it');

-- inventory_stock constraints.
select extensions.lives_ok($$insert into public.inventory_stock (id,organization_id,branch_id,item_id,quantity_on_hand,reorder_level_override) values ('f0400000-0000-0000-0000-000000000002','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000002',0,5)$$,'a zero-quantity stock row with a branch override is accepted');
select extensions.is((select version=1 from public.inventory_stock where id='f0400000-0000-0000-0000-000000000002'),true,'inventory_stock starts at version one');
select extensions.throws_ok($$insert into public.inventory_stock (organization_id,branch_id,item_id,quantity_on_hand) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001',-1)$$,'23514',null,'inventory_stock quantity_on_hand cannot be negative');
select extensions.throws_ok($$insert into public.inventory_stock (organization_id,branch_id,item_id,reorder_level_override) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001',-1)$$,'23514',null,'inventory_stock reorder_level_override cannot be negative');
select extensions.throws_ok($$insert into public.inventory_stock (id,organization_id,branch_id,item_id,version) values ('f0400000-0000-0000-0000-000000000003','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001',0)$$,'23514',null,'inventory_stock version must be positive');
select extensions.throws_ok($$insert into public.inventory_stock (organization_id,branch_id,item_id,quantity_on_hand) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001',1)$$,'23505',null,'the (organization_id, branch_id, item_id) key rejects duplicate stock rows');
select extensions.throws_ok($$insert into public.inventory_stock (organization_id,branch_id,item_id,quantity_on_hand) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000003','f0300000-0000-0000-0000-000000000001',1)$$,'23503',null,'inventory_stock rejects a foreign-organization branch');
select extensions.throws_ok($$insert into public.inventory_stock (organization_id,branch_id,item_id,quantity_on_hand) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000003',1)$$,'23503',null,'inventory_stock rejects a foreign-organization item');

-- inventory_transfers constraints.
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity,status) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',0,'SENT')$$,'23514',null,'inventory transfer quantity must be positive');
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001',1)$$,'23514',null,'an inventory transfer source and destination branch must differ');
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity,status) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',1,'LOST')$$,'23514',null,'inventory transfer status is bounded to SENT/PENDING_RECEIPT/RECEIVED/CANCELLED');
select extensions.throws_ok($$insert into public.inventory_transfers (id,organization_id,source_branch_id,destination_branch_id,item_id,quantity,status) values ('f0500000-0000-0000-0000-000000000003','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',1,'RECEIVED')$$,'23514',null,'a RECEIVED transfer requires confirmed_by and confirmed_at');
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity,status,reason) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',1,'SENT','   ')$$,'23514',null,'inventory transfer reasons cannot be blank');
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000003','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',1)$$,'23503',null,'inventory_transfers rejects a foreign-organization source branch');
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000003','f0300000-0000-0000-0000-000000000001',1)$$,'23503',null,'inventory_transfers rejects a foreign-organization destination branch');
select extensions.throws_ok($$insert into public.inventory_transfers (organization_id,source_branch_id,destination_branch_id,item_id,quantity) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000003',1)$$,'23503',null,'inventory_transfers rejects a foreign-organization item');
select extensions.lives_ok($$update public.inventory_transfers set status='RECEIVED', confirmed_by='e1010000-0000-0000-0000-000000000001', confirmed_at=statement_timestamp(), version=2 where id='f0500000-0000-0000-0000-000000000001'$$,'a RECEIVED transfer with both confirmation stamps is accepted');
select extensions.throws_ok($$update public.inventory_transfers set status='SENT', version=3 where id='f0500000-0000-0000-0000-000000000001'$$,'23514',null,'a transfer leaving RECEIVED must drop its confirmation stamps');
select extensions.throws_ok($$insert into public.inventory_transfers (id,organization_id,source_branch_id,destination_branch_id,item_id,quantity,status,confirmed_by) values ('f0500000-0000-0000-0000-000000000004','f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000002','f0300000-0000-0000-0000-000000000001',1,'SENT','e1010000-0000-0000-0000-000000000001')$$,'23514',null,'a non-RECEIVED transfer cannot carry confirmation stamps');

-- inventory_movements constraints and the append-only ledger.
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001','ADJUSTMENT',0)$$,'23514',null,'inventory movement quantity_delta cannot be zero');
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001','LOST',1)$$,'23514',null,'inventory movement type is bounded to RECEIPT/ADJUSTMENT/ISSUE/TRANSFER_OUT/TRANSFER_IN');
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta,reason) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001','ISSUE',-1,repeat('r',501))$$,'23514',null,'inventory movement reasons are bounded to 500 characters');
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta,lot_number) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001','RECEIPT',1,repeat('l',101))$$,'23514',null,'inventory movement lot numbers are bounded to 100 characters');
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000003','f0300000-0000-0000-0000-000000000001','RECEIPT',1)$$,'23503',null,'inventory movements rejects a foreign-organization branch');
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000003','RECEIPT',1)$$,'23503',null,'inventory movements rejects a foreign-organization item');
select extensions.throws_ok($$insert into public.inventory_movements (organization_id,branch_id,item_id,movement_type,quantity_delta,transfer_id) values ('f0100000-0000-0000-0000-000000000001','f0200000-0000-0000-0000-000000000001','f0300000-0000-0000-0000-000000000001','TRANSFER_IN',1,'f0500000-0000-0000-0000-000000000002')$$,'23503',null,'inventory movements rejects a foreign-organization transfer link');
select extensions.throws_ok($$update public.inventory_movements set quantity_delta=6 where id='f0600000-0000-0000-0000-000000000001'$$,'23514',null,'inventory movements cannot be updated');
select extensions.throws_ok($$delete from public.inventory_movements where id='f0600000-0000-0000-0000-000000000001'$$,'23514',null,'inventory movements cannot be deleted');

with test_failures as (select finish from extensions.finish() where finish !~ '^1\.\.[0-9]+$')
select case when count(*)=0 then 'P1_TEST_PASS' else string_agg(finish,E'\n') end as p1_test_result from test_failures;

rollback;